/**
 * The history graph and its key-points cards.
 *
 *  - Nodes: every persisted omp session, merged with the live ones (a live worker knows the newest title and
 *    activity), with the stored key points and, when a workspace resolver is given, the workspace of its cwd.
 *  - Edges: forks (the `parentSession` of a session header, resolved to the parent's id) and the edges deck recorded
 *    itself (`recordEdge`: handoff, move, plan-run).
 *  - Cards: generated by the session's own worker (smol role). A session gets a card after `idleMs` without activity,
 *    and when it is stopped (`summarizeBeforeStop`). Each idle stretch is tried once, so a session the model cannot
 *    summarise is not retried every poll.
 */
import type { HistoryEdge, HistoryNode, HistoryResponse, KeyPoints, SessionSummary } from "@omp-console/protocol";
import { titleFromFirstMessage } from "../recent";
import { readSessionConversation } from "../librarian/transcript";
import type { HistoryPorts, PersistedSession } from "./ports";
import { listPersisted, type PersistedLister } from "./persisted";
import { search } from "./search";
import { edgeKey, HistoryStore, parseEdge } from "./store";

export const DEFAULT_IDLE_SUMMARY_MS = 10 * 60 * 1000;
const DEFAULT_POLL_MS = 30_000;
const DEFAULT_LIST_TTL_MS = 5_000;
export const DEFAULT_HISTORY_LIMIT = 200;
export const MAX_HISTORY_LIMIT = 1000;

export interface HistoryOptions {
	/** Persisted sessions; default `SessionManager.listAll()`. */
	listPersisted?: PersistedLister;
	/** Workspace id of a cwd (the workspaces area); without it nodes carry no `workspaceId` and the workspace filter matches nothing. */
	workspaceOf?: (cwd: string) => string | undefined;
	now?: () => number;
	/** Idle time after which a live session gets key points (default 10 min). */
	idleMs?: number;
	/** How often idle sessions are looked for (default 30 s); `0` disables the timer. */
	pollMs?: number;
	/** How long a persisted-session listing is reused (default 5 s). */
	listTtlMs?: number;
	log?: (message: string) => void;
}

export interface HistoryQuery {
	workspace?: string;
	q?: string;
	limit?: number;
}

export class HistoryService {
	readonly #ports: HistoryPorts;
	readonly #store: HistoryStore;
	readonly #listPersisted: PersistedLister;
	readonly #workspaceOf: ((cwd: string) => string | undefined) | undefined;
	readonly #now: () => number;
	readonly #idleMs: number;
	readonly #listTtlMs: number;
	readonly #log: (message: string) => void;
	readonly #inFlight = new Map<string, Promise<KeyPoints | undefined>>();
	/** `lastActivityAt` of the idle stretch each session was last tried for. */
	readonly #attempted = new Map<string, number>();
	#edges: Promise<Map<string, HistoryEdge>> | undefined;
	#persisted: { at: number; sessions: PersistedSession[] } | undefined;
	#timer: Timer | undefined;
	#polling = false;
	#disposed = false;

	constructor(ports: HistoryPorts, stateDir: string, options: HistoryOptions = {}) {
		this.#ports = ports;
		this.#store = new HistoryStore(stateDir);
		this.#listPersisted = options.listPersisted ?? listPersisted;
		this.#workspaceOf = options.workspaceOf;
		this.#now = options.now ?? Date.now;
		this.#idleMs = options.idleMs ?? DEFAULT_IDLE_SUMMARY_MS;
		this.#listTtlMs = options.listTtlMs ?? DEFAULT_LIST_TTL_MS;
		this.#log = options.log ?? (() => {});
		const pollMs = options.pollMs ?? DEFAULT_POLL_MS;
		if (pollMs > 0) {
			this.#timer = setInterval(() => void this.poll(), pollMs);
			this.#timer.unref();
		}
	}

	#loadEdges(): Promise<Map<string, HistoryEdge>> {
		this.#edges ??= this.#store.readEdges().then(edges => new Map(edges.map(edge => [edgeKey(edge), edge])));
		return this.#edges;
	}

	/** Records a relation deck created (handoff, move, plan-run, or a fork it made); repeated edges are stored once. */
	async recordEdge(edge: HistoryEdge): Promise<void> {
		const valid = parseEdge(edge);
		if (!valid) throw new Error("an edge needs non-empty from and to ids and a kind of fork, handoff, move or plan-run");
		const edges = await this.#loadEdges();
		const key = edgeKey(valid);
		if (edges.has(key)) return;
		edges.set(key, valid);
		await this.#store.appendEdge(valid);
	}

	async #persistedSessions(): Promise<PersistedSession[]> {
		const cached = this.#persisted;
		const now = this.#now();
		if (cached && now - cached.at < this.#listTtlMs) return cached.sessions;
		const sessions = await this.#listPersisted();
		this.#persisted = { at: now, sessions };
		return sessions;
	}

	async graph(query: HistoryQuery = {}): Promise<HistoryResponse> {
		const [persisted, cards, recorded] = await Promise.all([this.#persistedSessions(), this.#store.readAllKeyPoints(), this.#loadEdges()]);
		const nodes = new Map<string, HistoryNode>();
		const idByFile = new Map<string, string>();
		for (const session of persisted) {
			idByFile.set(session.file, session.id);
			const node: HistoryNode = {
				sessionId: session.id,
				sessionFile: session.file,
				title: session.title ?? titleFromFirstMessage(session.firstMessage) ?? "Untitled session",
				createdAt: session.createdAt,
				lastActivityAt: session.modifiedAt,
			};
			const workspaceId = this.#workspaceOf?.(session.cwd);
			if (workspaceId !== undefined) node.workspaceId = workspaceId;
			nodes.set(session.id, node);
		}
		for (const live of this.#ports.list()) this.#mergeLive(nodes, idByFile, live);
		for (const node of nodes.values()) {
			const card = cards.get(node.sessionId);
			if (card) node.keyPoints = card;
		}

		let selected = [...nodes.values()];
		if (query.workspace) selected = selected.filter(node => node.workspaceId === query.workspace);
		selected = query.q ? search(selected, query.q) : selected.sort((a, b) => b.lastActivityAt - a.lastActivityAt);
		const limit = Math.min(Math.max(1, query.limit ?? DEFAULT_HISTORY_LIMIT), MAX_HISTORY_LIMIT);
		selected = selected.slice(0, limit);

		const included = new Set(selected.map(node => node.sessionId));
		const edges = new Map<string, HistoryEdge>();
		const add = (edge: HistoryEdge): void => {
			if (included.has(edge.from) && included.has(edge.to) && edge.from !== edge.to) edges.set(edgeKey(edge), edge);
		};
		for (const session of persisted) {
			const parent = session.parentSession === undefined ? undefined : (nodes.has(session.parentSession) ? session.parentSession : idByFile.get(session.parentSession));
			if (parent !== undefined) add({ from: parent, to: session.id, kind: "fork" });
		}
		for (const edge of recorded.values()) add(edge);
		return { nodes: selected, edges: [...edges.values()] };
	}

	#mergeLive(nodes: Map<string, HistoryNode>, idByFile: Map<string, string>, live: SessionSummary): void {
		const existing = nodes.get(live.id);
		const workspaceId = this.#workspaceOf?.(live.cwd);
		if (existing) {
			if (live.title !== undefined) existing.title = live.title;
			existing.lastActivityAt = Math.max(existing.lastActivityAt, live.lastActivityAt);
			if (existing.workspaceId === undefined && workspaceId !== undefined) existing.workspaceId = workspaceId;
			return;
		}
		const node: HistoryNode = {
			sessionId: live.id,
			title: live.title ?? "Untitled session",
			createdAt: live.createdAt,
			lastActivityAt: live.lastActivityAt,
		};
		if (live.sessionFile !== undefined) {
			node.sessionFile = live.sessionFile;
			idByFile.set(live.sessionFile, live.id);
		}
		if (workspaceId !== undefined) node.workspaceId = workspaceId;
		nodes.set(live.id, node);
	}

	/** Regenerates the key points of a live session and stores them; rejects with the worker's refusal. */
	async summarize(sessionId: string): Promise<KeyPoints> {
		const pending = this.#inFlight.get(sessionId);
		if (pending) {
			const card = await pending;
			if (card) return card;
		}
		const run = this.#ports.summarize(sessionId).then(async card => {
			await this.#store.writeKeyPoints(card);
			return card;
		});
		this.#inFlight.set(sessionId, run.catch(() => undefined));
		try {
			return await run;
		} finally {
			this.#inFlight.delete(sessionId);
		}
	}

	/** Whether the stored card of a session is missing or older than the session's last activity. */
	async #isStale(live: SessionSummary): Promise<boolean> {
		const card = await this.#store.readKeyPoints(live.id);
		return card === undefined || card.generatedAt < live.lastActivityAt;
	}

	/** Summarises every idle live session whose card is missing or stale, once per idle stretch. */
	async poll(): Promise<void> {
		if (this.#polling || this.#disposed) return;
		this.#polling = true;
		try {
			const now = this.#now();
			const live = this.#ports.list();
			const liveIds = new Set(live.map(session => session.id));
			for (const id of this.#attempted.keys()) if (!liveIds.has(id)) this.#attempted.delete(id);
			for (const session of live) {
				if (this.#disposed) return;
				if (session.state === "asleep") {
					this.#attempted.delete(session.id);
					continue;
				}
				if (session.state !== "idle" || now - session.lastActivityAt < this.#idleMs) continue;
				if (this.#attempted.get(session.id) === session.lastActivityAt) continue;
				this.#attempted.set(session.id, session.lastActivityAt);
				try {
					if (await this.#isStale(session)) await this.summarize(session.id);
				} catch (error) {
					this.#log(`history: key points for ${session.id} skipped: ${error instanceof Error ? error.message : String(error)}`);
				}
			}
		} finally {
			this.#polling = false;
		}
	}

	/** Key points for a session that is about to be stopped, while its worker still holds the transcript. Never throws. */
	async summarizeBeforeStop(sessionId: string): Promise<void> {
		const live = this.#ports.list().find(session => session.id === sessionId);
		// Hidden sessions (the agenda Ask session) are not History: no model call when one is stopped.
		if (!live || live.hidden) return;
		try {
			if (await this.#isStale(live)) await this.summarize(sessionId);
		} catch (error) {
			this.#log(`history: key points for ${sessionId} at stop skipped: ${error instanceof Error ? error.message : String(error)}`);
		}
	}
	/** Persists a transcript excerpt without a model call so an early sleep has a useful, refreshable history card. */
	async beforeSleep(sessionId: string): Promise<void> {
		const live = this.#ports.list().find(session => session.id === sessionId);
		if (!live || live.hidden || live.sessionFile === undefined) return;
		try {
			if (!(await this.#isStale(live))) return;
			const messages = await readSessionConversation(live.sessionFile);
			if (messages.length === 0) return;
			let firstUser: string | undefined;
			let lastAssistant: string | undefined;
			for (const message of messages) {
				if (message.role === "user") {
					firstUser ??= message.text;
				} else {
					lastAssistant = message.text;
				}
			}
			const previous = await this.#store.readKeyPoints(sessionId);
			const keyPoints: KeyPoints = {
				sessionId,
				title: live.title ?? firstUser?.slice(0, 120) ?? "Untitled session",
				decisions: previous?.decisions ?? [],
				files: previous?.files ?? [],
				openQuestions: previous?.openQuestions ?? [],
				generatedAt: Math.max(0, live.lastActivityAt - 1),
			};
			if (firstUser !== undefined) keyPoints.goal = firstUser;
			const outcome = lastAssistant ?? previous?.outcome;
			if (outcome !== undefined) keyPoints.outcome = outcome;
			await this.#store.writeKeyPoints(keyPoints);
		} catch (error) {
			this.#log(`history: model-free key points for ${sessionId} at sleep skipped: ${error instanceof Error ? error.message : String(error)}`);
		}
	}

	dispose(): void {
		this.#disposed = true;
		clearInterval(this.#timer);
		this.#timer = undefined;
	}
}
